import {CREDIT_KEY,loadCredits,spendDraw,rewardShare} from './credits.130ed36e7bb4.js';
import {choose,probability,percentage} from './engine.ef1ad2c5f0ec.js';
// The dev server sets the document base to the local origin; production uses the build's public URL.
const $=id=>document.getElementById(id);let countries=[],excluded=[],mode='population',current=null,busy=false;
try{const saved=JSON.parse(localStorage.getItem('rebirth-fr-settings')||'{}');excluded=Array.isArray(saved.excluded)?saved.excluded.slice(0,3):[];mode=saved.mode==='equal'?'equal':'population';}catch{}
let store;try{store=window.localStorage;}catch{}const credits=loadCredits(store);
function saveCredits(){try{store.setItem(CREDIT_KEY,JSON.stringify(credits));}catch{toast('Le stockage du navigateur est bloqué ; le compteur ne peut pas être enregistré.');}}
function updateCredits(){$('retry').disabled=credits.remaining===0;$('retry').textContent=credits.remaining?`↻ Retirer · ${credits.remaining} restant(s)`:'Aucun tirage restant';$('credit-status').textContent=`${credits.remaining} tirage(s) restant(s) · partager donne +2`;$('share-rule').textContent=credits.rewardedRound===credits.round?"Bonus de partage déjà reçu pour cette carte":"Un bonus par carte · demande de partage ou lien copié";$('draw').textContent=credits.started?(credits.remaining?`Nouveau tirage · ${credits.remaining} restant(s)`:'Voir et partager mon passeport ↗'):'Tirer ma prochaine vie ↗';}
document.querySelector(`input[name=mode][value=${mode}]`).checked=true;
let toastTimer;function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3200);}
function persist(){try{localStorage.setItem('rebirth-fr-settings',JSON.stringify({mode,excluded}));}catch{}}
function screen(name){for(const id of ['home','loading','result'])$(id).hidden=id!==name;$('explore').hidden=name==='loading';}
function result(c,{navigate=true}={}){current=c;updateCredits();screen('result');$('result-title').textContent=c.name;$('passport-country').textContent=c.name;$('passport-english').textContent=c.english;$('passport').style.setProperty('--cover',c.color);$('ticket-destination').textContent=c.name;$('result-probability').textContent=percentage(probability(c,countries,mode,excluded))+'%';$('result-color').textContent=c.colorName;$('result-region').textContent=c.region;$('result-population').textContent=new Intl.NumberFormat("fr-FR",{notation:'compact',maximumFractionDigits:1}).format(c.population)+' personnes';$('result-mode').textContent=(mode==='equal'?"Chances égales":"Pondération démographique")+(excluded.length?` · ${excluded.length} exclus`:'');if(navigate){history.pushState({view:'result',code:c.code},'',shareURL(c));window.scrollTo({top:0,behavior:'smooth'});}document.title=`Ma prochaine vie : ${c.name} · Passeport de réincarnation`;}
function shareURL(c){const url=new URL(`r/${c.code}/`,document.baseURI);url.searchParams.set('card','3');if(mode==='equal')url.searchParams.set('mode','equal');if(excluded.length)url.searchParams.set('exclude',excluded.join(','));return url.href;}
async function draw(){if(busy||!countries.length)return;if(!spendDraw(credits)){const previous=countries.find(c=>c.code===credits.lastCode);if(previous)result(previous);toast('Une action de partage ou un lien copié ajoute 2 tirages.');return;}saveCredits();busy=true;$('draw').disabled=true;screen('loading');window.scrollTo({top:0,behavior:'smooth'});const timer=setInterval(()=>{$('loading-name').textContent=countries[Math.floor(Math.random()*countries.length)].name+' — tirage en cours';},140);await new Promise(r=>setTimeout(r,matchMedia('(prefers-reduced-motion: reduce)').matches?150:2200));clearInterval(timer);const picked=choose(countries,mode,excluded);credits.lastCode=picked.code;saveCredits();result(picked);busy=false;$('draw').disabled=false;}
$('draw').addEventListener('click',draw);$('retry').addEventListener('click',draw);
document.querySelectorAll('input[name=mode]').forEach(input=>input.addEventListener('change',()=>{mode=input.value;persist();}));
for(const name of ['about','browse','sources']){$(name+'-open').onclick=()=>{$(name).showModal();if(name==='browse')renderList();};$(name).querySelectorAll('.close,.dialog-ok').forEach(b=>b.onclick=()=>$(name).close());$(name).addEventListener('click',e=>{if(e.target===$(name)){const r=$(name).getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$(name).close();}});}
function renderList(){const query=$('search').value.trim().toLocaleLowerCase();$('excluded-count').textContent=`Exclus : ${excluded.length} / 3`;$('country-list').replaceChildren();const found=countries.filter(c=>c.name.toLocaleLowerCase().includes(query)||c.english.toLocaleLowerCase().includes(query));if(!found.length){$('country-list').textContent='Aucun résultat.';return;}for(const c of found){const row=document.createElement('label');row.className='country-row';row.style.setProperty('--cover',c.color);const input=document.createElement('input');input.type='checkbox';input.checked=excluded.includes(c.code);input.disabled=!input.checked&&excluded.length>=3;input.setAttribute('aria-label',c.name+' à exclure');const dot=document.createElement('span');dot.className='color-dot';const name=document.createElement('span');name.textContent=c.name;const probabilityLabel=document.createElement('small');probabilityLabel.textContent=c.colorName;row.append(input,dot,name,probabilityLabel);input.onchange=()=>{excluded=input.checked?[...excluded,c.code]:excluded.filter(code=>code!==c.code);persist();renderList();};$('country-list').append(row);}}
$('search').oninput=renderList;
function grantShare(){if(rewardShare(credits)){saveCredits();updateCredits();toast('Bonus de partage : 2 tirages ajoutés.');}else toast('Le bonus de ce passeport a déjà été reçu.');}
async function copy(){if(!current)return;let copied=false;try{await navigator.clipboard.writeText(shareURL(current));copied=true;}catch{const input=document.createElement('textarea');input.value=shareURL(current);document.body.append(input);input.select();copied=document.execCommand('copy');input.remove();}if(copied)grantShare();else toast('La copie est bloquée.');}
$('copy').onclick=copy;$('share').onclick=async()=>{if(!current)return;if(navigator.share){try{await navigator.share({title:'Ma prochaine vie : '+current.name,text:'Quel pays tireras-tu pour ta prochaine vie ?',url:shareURL(current)});grantShare();}catch(e){if(e.name!=='AbortError')toast('Impossible d’ouvrir le partage. Utilise la copie du lien.');}}else toast('Ce navigateur ne permet pas d’ouvrir le partage. Utilise la copie du lien.');};
function socialShare(network){if(!current)return;const url=encodeURIComponent(shareURL(current)),text=encodeURIComponent('Ma prochaine vie : '+current.name+' ! Quel pays tireras-tu ?');const target=network==='x'?'https://x.com/intent/tweet?text='+text+'&url='+url:'https://www.facebook.com/sharer/sharer.php?u='+url;const popup=window.open(target,'_blank','width=640,height=640');if(popup){popup.opener=null;grantShare();}else toast('La fenêtre de partage est bloquée. Utilise la copie du lien.');}
$('share-x').onclick=()=>socialShare('x');$('share-facebook').onclick=()=>socialShare('facebook');
$('save').onclick=()=>{if(!current)return;const a=document.createElement('a');a.href=new URL(`og/${current.code}.jpg?v=3`,document.baseURI).href;a.download=`rebirth-${current.code}.jpg`;document.body.append(a);a.click();a.remove();toast('Enregistrement JPG lancé.');};
addEventListener('popstate',event=>{const c=event.state?.view==='result'?countries.find(c=>c.code===event.state.code):null;if(c)result(c,{navigate:false});else{screen('home');current=null;document.title='Tirer un pays de réincarnation · Passeport de réincarnation';}});
async function init(){updateCredits();screen('home');history.replaceState({view:'home'},'',location.href);document.title='Tirer un pays de réincarnation · Passeport de réincarnation';try{const response=await fetch(new URL('countries.json',document.baseURI));if(!response.ok)throw Error();countries=await response.json();excluded=excluded.filter(code=>countries.some(c=>c.code===code));for(const code of ['KR','CH','NZ','IT']){const c=countries.find(c=>c.code===code);const card=document.createElement('article');card.className='sample-card';card.style.setProperty('--cover',c.color);card.innerHTML=`<div class="sample-book" aria-hidden="true"><span>${c.code} · RÉINCARNATION</span><b>✳</b><small>PASSEPORT</small></div><div class="sample-details"><small>${c.english}</small><h3>${c.name}</h3><p><i></i>${c.colorName}</p></div>`;$('sample-grid').append(card);}startGlobe();}catch{toast('Impossible de charger les pays. Recharge la page.');$('draw').textContent='Recharger et recommencer';$('draw').onclick=()=>location.reload();}}
async function startGlobe(){const canvas=$('globe'),ctx=canvas.getContext('2d');let geometry;try{geometry=await(await fetch(new URL('land.json',document.baseURI))).json();}catch{}let angle=-105;const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;const rad=Math.PI/180;function project(lon,lat){const l=(lon+angle)*rad,p=lat*rad;const tilt=15*rad;return[Math.cos(p)*Math.sin(l),Math.cos(tilt)*Math.sin(p)-Math.sin(tilt)*Math.cos(p)*Math.cos(l),Math.sin(tilt)*Math.sin(p)+Math.cos(tilt)*Math.cos(p)*Math.cos(l)];}function drawGlobe(){ctx.clearRect(0,0,900,900);ctx.save();ctx.translate(450,450);ctx.scale(405,-405);ctx.beginPath();ctx.arc(0,0,1,0,Math.PI*2);ctx.fillStyle='#dce2c8';ctx.fill();ctx.clip();ctx.strokeStyle='#bec8a4';ctx.lineWidth=.0017;for(let lat=-60;lat<=60;lat+=30){ctx.beginPath();let prev=false;for(let lon=-180;lon<=180;lon+=2){const[x,y,z]=project(lon,lat);if(z>0){prev?ctx.lineTo(x,y):ctx.moveTo(x,y);prev=true;}else prev=false;}ctx.stroke();}for(let lon=-180;lon<180;lon+=30){ctx.beginPath();let prev=false;for(let lat=-90;lat<=90;lat+=2){const[x,y,z]=project(lon,lat);if(z>0){prev?ctx.lineTo(x,y):ctx.moveTo(x,y);prev=true;}else prev=false;}ctx.stroke();}ctx.fillStyle='#2c4dca';if(geometry){const polygons=geometry.type==='MultiPolygon'?geometry.coordinates:[geometry.coordinates];for(const polygon of polygons){for(const ring of polygon){const points=ring.map(([lon,lat])=>project(lon,lat));if(!points.some(p=>p[2]>0))continue;ctx.beginPath();points.forEach(([x,y,z],i)=>{const length=Math.hypot(x,y);if(z<0){x/=length;y/=length;}i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.closePath();ctx.fill();}}}ctx.restore();if(!reduce){angle+=.025;requestAnimationFrame(drawGlobe);}}drawGlobe();}init();
